select json_build_object('audit', to_regclass('public.member_audit') is not null, 'invitations', to_regclass('public.member_invitations') is not null, 'guard', to_regprocedure('public.guard_member()') is not null, 'remove_member', to_regprocedure('public.remove_member(uuid,uuid)') is not null, 'removed_at', exists(select 1 from information_schema.columns where table_schema='public' and table_name='members' and column_name='removed_at'), 'claimed_at', exists(select 1 from information_schema.columns where table_schema='public' and table_name='member_invitations' and column_name='claimed_at'));
